# -*- coding: utf-8 -*-
"""Генератор научного документа по OpenSetAnalyzer."""

import os
from docx import Document
from docx.shared import Pt, Cm, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.style import WD_STYLE_TYPE
from docx.oxml.ns import qn
from docx.oxml import OxmlElement

OUTPUT_PATH = os.path.join(os.path.dirname(__file__), "OpenSetAnalyzer_Scientific_Description.docx")


def set_page_margins(doc, top=2.5, bottom=2.5, left=3.0, right=1.5):
    for section in doc.sections:
        section.top_margin = Cm(top)
        section.bottom_margin = Cm(bottom)
        section.left_margin = Cm(left)
        section.right_margin = Cm(right)


def add_paragraph(doc, text, style="Normal", bold=False, italic=False, align=None,
                  space_before=None, space_after=None, first_line_indent=None,
                  font_size=None, font_name=None):
    p = doc.add_paragraph(style=style)
    run = p.add_run(text)
    run.bold = bold
    run.italic = italic
    if font_size:
        run.font.size = Pt(font_size)
    if font_name:
        run.font.name = font_name
    pf = p.paragraph_format
    if align:
        pf.alignment = align
    if space_before is not None:
        pf.space_before = Pt(space_before)
    if space_after is not None:
        pf.space_after = Pt(space_after)
    if first_line_indent is not None:
        pf.first_line_indent = Cm(first_line_indent)
    return p


def add_heading(doc, text, level=1):
    p = doc.add_heading(text, level=level)
    p.paragraph_format.space_before = Pt(18 if level == 1 else 12)
    p.paragraph_format.space_after = Pt(6)
    return p


def body(doc, text):
    p = doc.add_paragraph()
    p.paragraph_format.first_line_indent = Cm(1.25)
    p.paragraph_format.space_after = Pt(0)
    p.paragraph_format.space_before = Pt(0)
    p.paragraph_format.line_spacing = Pt(18)
    run = p.add_run(text)
    run.font.size = Pt(14)
    run.font.name = "Times New Roman"
    p.paragraph_format.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    return p


def formula(doc, text):
    p = doc.add_paragraph()
    p.paragraph_format.first_line_indent = Cm(0)
    p.paragraph_format.space_before = Pt(6)
    p.paragraph_format.space_after = Pt(6)
    p.paragraph_format.alignment = WD_ALIGN_PARAGRAPH.CENTER
    run = p.add_run(text)
    run.font.size = Pt(13)
    run.font.name = "Courier New"
    run.bold = True
    return p


def caption(doc, text):
    p = doc.add_paragraph()
    p.paragraph_format.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.space_before = Pt(2)
    p.paragraph_format.space_after = Pt(12)
    run = p.add_run(text)
    run.font.size = Pt(12)
    run.font.name = "Times New Roman"
    run.italic = True
    return p


def build_document():
    doc = Document()
    set_page_margins(doc)

    # Настройка Normal style
    style = doc.styles["Normal"]
    font = style.font
    font.name = "Times New Roman"
    font.size = Pt(14)

    # Настройка Heading 1
    h1 = doc.styles["Heading 1"]
    h1.font.name = "Times New Roman"
    h1.font.size = Pt(16)
    h1.font.bold = True
    h1.font.color.rgb = RGBColor(0, 0, 0)

    # Настройка Heading 2
    h2 = doc.styles["Heading 2"]
    h2.font.name = "Times New Roman"
    h2.font.size = Pt(15)
    h2.font.bold = True
    h2.font.italic = False
    h2.font.color.rgb = RGBColor(0, 0, 0)

    # Настройка Heading 3
    h3 = doc.styles["Heading 3"]
    h3.font.name = "Times New Roman"
    h3.font.size = Pt(14)
    h3.font.bold = True
    h3.font.italic = True
    h3.font.color.rgb = RGBColor(0, 0, 0)

    # ─────────────────────────────────────
    # ТИТУЛЬНАЯ ИНФОРМАЦИЯ
    # ─────────────────────────────────────
    p = doc.add_paragraph()
    p.paragraph_format.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.space_before = Pt(0)
    p.paragraph_format.space_after = Pt(6)
    r = p.add_run("ПРОГРАММНЫЙ МОДУЛЬ OPEN-SET DETECTION ДЛЯ СИСТЕМ\nВИЗУАЛЬНОГО МОНИТОРИНГА: АРХИТЕКТУРА, АЛГОРИТМЫ\nИ ПРАКТИЧЕСКАЯ РЕАЛИЗАЦИЯ")
    r.font.name = "Times New Roman"
    r.font.size = Pt(16)
    r.font.bold = True

    p = doc.add_paragraph()
    p.paragraph_format.alignment = WD_ALIGN_PARAGRAPH.CENTER
    r = p.add_run("Описание программного плагина OpenSetAnalyzer\nсистемы Watch Golem")
    r.font.name = "Times New Roman"
    r.font.size = Pt(13)
    r.italic = True

    doc.add_paragraph()

    # ─────────────────────────────────────
    # АННОТАЦИЯ
    # ─────────────────────────────────────
    add_heading(doc, "Аннотация", level=1)
    body(doc, "Настоящий документ представляет собой подробное техническое и теоретическое описание программного плагина OpenSetAnalyzer, разработанного в составе системы автоматизированного видеомониторинга Watch Golem. Плагин реализует концепцию открытого множества (open-set detection), при которой система не ограничивается заранее заданным списком классов, а способна обнаруживать и маркировать объекты, не входящие в обучающий словарь. В работе описаны теоретические основы задачи, архитектурные решения, математический аппарат оценки новизны, алгоритмы кластеризации неизвестных объектов, а также практические особенности реализации на языке Python с использованием нейросетевых компонентов YOLOv11, OpenCLIP ViT-B-32 и монокулярного оценщика глубины DPT-Hybrid.")

    doc.add_paragraph()

    # ─────────────────────────────────────
    # 1. ВВЕДЕНИЕ
    # ─────────────────────────────────────
    add_heading(doc, "1. Введение", level=1)

    body(doc, "Задача обнаружения объектов на изображениях и в видеопотоке является одной из центральных в области компьютерного зрения. На протяжении многих лет её развитие шло по пути closed-set постановки: исследователи обучали детекторы распознавать строго ограниченный набор классов — автомобиль, пешеход, знак, животное, — и весь мир, не входящий в этот набор, детектором попросту игнорировался. Подобный подход прекрасно работает в контролируемых лабораторных условиях, однако в реальных сценариях видеонаблюдения такое ограничение оказывается существенным недостатком.")

    body(doc, "Представим систему видеоаналитики, установленную на промышленном объекте. Помимо привычных категорий — люди, транспортные средства, оборудование — на монитор может попасть нечто нестандартное: предмет, оставленный кем-то в неположенном месте, неизвестное животное, необычный инструмент или даже нераспознанная угроза. Классический детектор воспримет подобный объект либо как фоновый шум, либо ошибочно классифицирует как наиболее похожий известный класс. Оба варианта с практической точки зрения неприемлемы.")

    body(doc, "Именно для решения описанной проблемы была сформулирована постановка open-set recognition (OSR) и, как её частный случай, open-set object detection (OSOD). Ключевая идея состоит в том, что система должна уметь отвечать «не знаю» — то есть детектировать регион на изображении и при низкой уверенности в принадлежности к какому-либо известному классу честно сообщить об этом оператору, а не выдавать ложную классификацию.")

    body(doc, "Плагин OpenSetAnalyzer является практической реализацией данной концепции для системы Watch Golem — программного комплекса, ориентированного на интеллектуальный анализ видеозаписей и фотоматериалов. Плагин разработан с расчётом на обработку как отдельных изображений, так и видеофайлов произвольной длины, эксплуатируется в режиме реального применения и не требует специализированной переработки или дообучения нейросетей.")

    body(doc, "Данная работа ставит перед собой несколько взаимосвязанных задач. Во-первых, необходимо дать строгое теоретическое определение задачи открытого множества и рассмотреть её в контексте смежных направлений. Во-вторых, требуется детальное описание каждого нейросетевого компонента, задействованного в конвейере плагина, с указанием принципов их работы и мотивации выбора. В-третьих, следует подробно разобрать алгоритмическую сторону — от генерации кандидатных регионов до кластеризации обнаруженных аномальных объектов. Наконец, в-четвёртых, важно обозначить ограничения предложенного решения и возможные направления дальнейшего развития.")

    # ─────────────────────────────────────
    # 2. ПОСТАНОВКА ЗАДАЧИ
    # ─────────────────────────────────────
    add_heading(doc, "2. Формальная постановка задачи обнаружения объектов в условиях открытого множества", level=1)

    body(doc, "Для строгого математического описания задачи введём необходимые обозначения. Пусть задано конечное множество известных семантических классов K = {k₁, k₂, ..., kₙ}, которые соответствуют категориям, включённым в обучающий словарь детекторной системы. В задаче closed-set detection прогноз модели для произвольного региона изображения x однозначно принадлежит одному из классов множества K.")

    body(doc, "В постановке открытого множества дополнительно существует класс U, обозначающий «неизвестный объект» (Unknown). Формально задача open-set detection состоит в построении функции f: X → K ∪ {U}, где X — пространство изображений (или их фрагментов). При этом система должна, опираясь исключительно на признаки входного изображения и не имея явных обучающих примеров класса U, принять обоснованное решение о принадлежности объекта к одному из известных классов или маркировать его как неизвестный.")

    body(doc, "В литературе данная задача обычно рассматривается в двух взаимосвязанных аспектах. Первый — это open-set recognition, при котором входом служит уже локализованный фрагмент изображения и задача сводится к классификации. Второй — open-set object detection, в котором система должна произвести и локализацию, и классификацию одновременно. OpenSetAnalyzer работает именно в рамках второго, более сложного варианта.")

    body(doc, "Ключевая сложность задачи состоит в принципиальной асимметрии информации: о классах K имеется достаточно примеров для обучения, тогда как о классе U никакой информации нет по определению. Это означает, что нельзя обучить стандартный бинарный классификатор «известный/неизвестный» в прямом смысле слова. Вместо этого необходимо строить меру новизны (novelty score) — функцию, которая возвращает высокое значение для объектов, существенно отличающихся от всех известных концептов.")

    body(doc, "В классической теории эта проблема формализуется через принцип открытости пространства (open space risk). Любой классификатор, обученный на закрытом множестве, вынужден заполнять всё пространство признаков решениями относительно известных классов: области «между» классами, удалённые от обучающих примеров, произвольно относятся к тому или иному классу, хотя на практике туда попадают именно неизвестные объекты. Задача OSOD состоит в минимизации открытого риска — вероятности ложной классификации при попадании в такие области.")

    body(doc, "Современные подходы к решению OSOD делятся на несколько групп. Первая группа — методы, основанные на явном обучении отторжения (rejection learning), при которых сеть дообучается на синтетически сгенерированных примерах класса «неизвестный». Вторая группа использует энергетические функции (energy-based models), в которых объекты с высокой энергией автоматически идентифицируются как out-of-distribution. Третья группа — подходы на основе нулевого опыта (zero-shot methods), позволяющие рассуждать о новых концептах через семантические эмбеддинги. OpenSetAnalyzer принадлежит именно к третьей группе: он использует контрастивную мультимодальную модель CLIP для нуль-шотной оценки схожести произвольного изображения с заданным набором текстовых описаний.")

    # ─────────────────────────────────────
    # 3. НЕЙРОСЕТЕВЫЕ КОМПОНЕНТЫ
    # ─────────────────────────────────────
    add_heading(doc, "3. Нейросетевые компоненты плагина", level=1)
    add_heading(doc, "3.1. Детектор объектов семейства YOLO", level=2)

    body(doc, "YOLO (You Only Look Once) — семейство одностадийных детекторов объектов, впервые предложенное Redmon и соавторами в 2015 году. В отличие от двустадийных архитектур типа Faster R-CNN, YOLO производит локализацию и классификацию объектов за один прямой проход нейронной сети, что обеспечивает значительный выигрыш по скорости при сравнимом качестве.")

    body(doc, "В своей основе YOLO делит входное изображение на сетку ячеек S×S. Каждая ячейка предсказывает B ограничивающих прямоугольников (bounding boxes) и оценку вероятности присутствия объекта в каждом из них (objectness score). Одновременно для каждого прямоугольника предсказывается вероятностное распределение по всем C известным классам. Финальный прогноз — совокупность пар (box, class_probability) — фильтруется порогом уверенности и подавлением немаксимумов (Non-Maximum Suppression, NMS).")

    body(doc, "Последующие версии серии значительно усовершенствовали исходную идею. YOLOv5 и YOLOv8, разрабатываемые компанией Ultralytics, ввели масштабно-инвариантное обнаружение с помощью многоуровневых карт признаков (Feature Pyramid Network, FPN), адаптивное якорное квантование и улучшенные функции потерь, включая DIoU и CIoU для более точной регрессии прямоугольников. YOLOv11 — актуальная версия серии — использует модифицированную архитектуру C3k2/C2PSA в составе backbone, дополнительно повышающую эффективность извлечения признаков при меньшем числе параметров.")

    body(doc, "В OpenSetAnalyzer YOLO выполняет роль первичного генератора кандидатных регионов. Важно подчеркнуть, что результаты классификации YOLO не принимаются за окончательный ответ: они используются лишь как сильные подсказки для формирования набора предложений (proposals). Данное архитектурное решение принято намеренно — YOLO обучен на закрытом множестве классов, и его классификационный выход принципиально ненадёжен для потенциально неизвестных объектов. Зато порождаемые им ограничивающие прямоугольники, как правило, достаточно точно локализуют любые визуально выделяющиеся регионы вне зависимости от их семантики.")

    body(doc, "Плагин поддерживает несколько весовых файлов: yolo11x.pt (extended, максимальное качество при более высоких вычислительных затратах), yolo11n.pt (nano, компактная модель для ресурсоограниченных сред) и yolov8n.pt в качестве запасного варианта. Выбор происходит автоматически путём поиска первого из доступных файлов в корневой директории проекта.")

    add_heading(doc, "3.2. Контрастивная мультимодальная модель OpenCLIP", level=2)

    body(doc, "CLIP (Contrastive Language-Image Pre-Training) был предложен исследовательской группой OpenAI в 2021 году и стал поворотной точкой в развитии мультимодального машинного обучения. Ключевая идея модели заключается в совместном обучении двух кодировщиков — изображений и текстовых описаний — таким образом, что представления семантически связанных пар (изображение, подпись) оказываются максимально близкими в общем векторном пространстве.")

    body(doc, "Обучение CLIP происходит на колоссальных наборах данных пар «изображение–текст», собранных из интернета (400 миллионов пар в оригинальной версии). Каждый батч обучения содержит N изображений и N соответствующих текстов; задача сети — максимизировать косинусное сходство между правильными парами и минимизировать его между неправильными. Это формирует мощное единое семантическое пространство, в котором расположены как визуальные, так и текстовые признаки.")

    body(doc, "OpenCLIP — это открытая переработка идеи CLIP от сообщества LAION, воспроизводящая (и часто превосходящая) оригинальную модель. Вариант ViT-B-32 («Base», patch size 32), задействованный в OpenSetAnalyzer, использует Vision Transformer в качестве визуального кодировщика — архитектуру, изначально разработанную для задач обработки естественного языка и адаптированную к изображениям путём разбиения последних на фиксированные прямоугольные патчи. Каждый патч переводится в эмбеддинг линейной проекцией, после чего последовательность эмбеддингов обрабатывается механизмом self-attention.")

    body(doc, "Принципиальным свойством CLIP для задачи open-set detection является zero-shot classifiability: модель может оценить семантическое сходство произвольного изображения с произвольной текстовой фразой без какого-либо дополнительного обучения. Это означает, что для каждого известного класса достаточно сформировать текстовое описание — и система немедленно получает «эталонный» вектор в общем пространстве. Объект, не подходящий ни к одному такому эталону, с высокой вероятностью является неизвестным.")

    body(doc, "Для повышения устойчивости оценки OpenSetAnalyzer применяет технику prompt ensembling — усреднение текстовых представлений по нескольким шаблонам: «a photo of a {label}», «a close-up photo of a {label}», «a cropped photo of a {label}», «a blurry photo of a {label}» и «an image of a {label}». Набор из N шаблонов к каждому известному классу дополнительно нивелирует разброс, связанный с формулировкой запроса.")

    formula(doc, "f̂(label) = normalize( mean_t [ CLIP_text(template_t(label)) ] )")
    caption(doc, "Формула 1 — Усреднённый текстовый эмбеддинг для одного класса по N шаблонам")

    body(doc, "Полученные усреднённые и нормализованные текстовые эмбеддинги кешируются в памяти процесса на время сессии, что исключает дорогостоящий повторный инференс модели для одного и того же набора классов.")

    add_heading(doc, "3.3. Монокулярная оценка глубины сцены: DPT-Hybrid MiDaS", level=2)

    body(doc, "Понимание пространственной структуры сцены является ценным дополнительным сигналом при анализе изображений. Знание, где именно находится объект относительно камеры — ближний, средний или дальний план, — позволяет корректировать уверенность детекции: маленький неизвестный объект на переднем плане заслуживает большего внимания, чем нечёткое пятно на горизонте. В OpenSetAnalyzer для этой цели используется модель Intel/dpt-hybrid-midas, более известная как DPT-Hybrid.")

    body(doc, "DPT (Dense Prediction Transformer) — семейство архитектур, адаптирующих Vision Transformer для задач попиксельного предсказания. В отличие от задачи классификации, где ViT возвращает один глобальный вектор, DPT извлекает карты признаков с нескольких слоёв трансформера, объединяет их через механизм reassembly и постепенного укрупнения (fusion) и формирует выходную карту с разрешением, приближённым к исходному. MiDaS (Mixed Dataset Supervision) — обучающая стратегия и набор предобученных моделей для задачи относительной глубины: модель учится предсказывать не абсолютные значения в метрах, а лишь относительное упорядочивание пикселей по глубине.")

    body(doc, "Это разграничение важно: DPT-Hybrid-MiDaS не является метрическим оценщиком, предоставляя безвекторную относительную карту. Однако для целей OpenSetAnalyzer этого вполне достаточно: необходимо лишь разделить объекты на группы «ближний», «средний» и «дальний» план, что легко достигается процентильной нормализацией карты глубины.")

    body(doc, "Из практических соображений инференс модели ограничен максимальным разрешением 512 пикселей по длинной стороне (параметр _DEPTH_MAX_SIDE): полноразрешённый ввод избыточен для задачи пространственного зонирования и значительно замедляет обработку. Таймаут инференса установлен в 20 секунд; при его превышении обработка продолжается без карты глубины.",)

    body(doc, "Следует отметить, что на CPU время инференса DPT-Hybrid составляет от 30 до 120 секунд на одно изображение, что совершенно непрактично. Поэтому модуль оценки глубины автоматически отключается при отсутствии CUDA-устройства. Данное ограничение является осознанным компромиссом между функциональностью и применимостью на массовом железе.")

    # ─────────────────────────────────────
    # 4. АРХИТЕКТУРА ПЛАГИНА
    # ─────────────────────────────────────
    add_heading(doc, "4. Общая архитектура плагина OpenSetAnalyzer", level=1)

    body(doc, "OpenSetAnalyzer построен как автономный Python-модуль, подключаемый к основному приложению Watch Golem через унифицированный интерфейс плагинов. Реализация сосредоточена в единственном файле open_set_analyzer.py и не требует никаких изменений в основном приложении для расширения функциональности.")

    body(doc, "Архитектурно модуль организован по принципу ленивой инициализации (lazy initialization): все тяжёлые нейросетевые модели — YOLO, OpenCLIP, DPT — загружаются в память только при первом обращении и остаются в ней до завершения процесса. Это позволяет избежать многократной загрузки с диска при батчевой обработке и существенно ускоряет обработку второго и последующих файлов в сессии.")

    body(doc, "Плагин предоставляет три основные публичные функции: analyze_open_set (обработка одного изображения), analyze_open_set_video (обработка видеофайла с выборочным анализом ключевых кадров) и analyze_open_set_folder (батчевая обработка смешанного набора изображений и видеофайлов из папки). Все три функции возвращают унифицированный словарь результатов, пригодный для дальнейшего отчётного форматирования.")

    body(doc, "Внутренний конвейер обработки каждого изображения (или кадра видео) включает следующие последовательные этапы: 1) генерацию кандидатных регионов; 2) оценку новизны через OpenCLIP; 3) вычисление карты глубины; 4) присвоение пространственных меток; 5) аннотирование изображения; 6) сохранение кропов неизвестных объектов; 7) кластеризацию неизвестных объектов по схожести. Каждый этап подробно рассмотрен в последующих разделах.")

    body(doc, "С точки зрения безопасности и устойчивости модуль имеет несколько защитных механизмов. Инференс карты глубины обёрнут в отдельный поток с жёстким таймаутом через concurrent.futures, что гарантирует отсутствие зависания основного процесса при проблемах с CUDA-ядрами. Загрузка моделей с HuggingFace Hub ограничена таймаутом в 30 секунд (переменная среды HF_HUB_DOWNLOAD_TIMEOUT). Для компонента safetensors отключена прямая загрузка на GPU (SAFETENSORS_FAST_GPU=0) во избежание ACCESS_VIOLATION на платформе Windows.")

    # ─────────────────────────────────────
    # 5. ГЕНЕРАЦИЯ ПРЕДЛОЖЕНИЙ
    # ─────────────────────────────────────
    add_heading(doc, "5. Этап 1: Генерация кандидатных регионов", level=1)
    add_heading(doc, "5.1. YOLO-предложения", level=2)

    body(doc, "Первый и наиболее информативный источник кандидатных регионов — детектор YOLO. Для каждого входного изображения выполняется инференс с порогом уверенности det_confidence (по умолчанию 0.15). Намеренно заниженный порог позволяет зафиксировать даже слабые срабатывания, которые при стандартных настройках фильтровались бы. Каждый регион, прошедший порог, расширяется на 8% от ширины и высоты (expand_box), чтобы включить некоторый контекстный ореол.")

    body(doc, "Каждому YOLO-предложению присваивается базовый скор score = conf + 0.35, что смещает YOLO-кандидаты наверх в сортировке перед NMS. Логика здесь следующая: YOLO, будучи специализированным детектором, геометрически точнее локализует объекты, чем контурный генератор. Дополнительные 0.35 — эвристический бонус приоритета, обеспечивающий выживание YOLO-регионов при конфликте с generic-предложениями в NMS.")

    add_heading(doc, "5.2. Генерация контурных предложений (Generic Proposals)", level=2)

    body(doc, "Второй источник кандидатов — геометрический генератор generic proposals, работающий исключительно на основе обработки изображения в оттенках серого без задействования каких-либо нейронных сетей. Его задача — обнаружить визуально выделяющиеся замкнутые области, которые могут соответствовать объектам, не входящим в словарь YOLO.")

    body(doc, "Алгоритм работает в несколько шагов. Исходное изображение переводится в оттенки серого и сглаживается фильтром Гаусса (ядро 5×5, σ=0). Затем применяется детектор границ Canny с нижним порогом 50 и верхним 150. Полученная карта границ морфологически замыкается (closing, ядро 5×5, 2 итерации) и дилатируется (1 итерация) для объединения фрагментированных контуров. На финальной маске извлекаются внешние контуры; для каждого вычисляется ограничивающий прямоугольник.")

    body(doc, "Кандидаты фильтруются по ряду критериев. Минимальная площадь устанавливается как max(32×32, 0.3% площади изображения). Минимальный линейный размер по каждой стороне — 24 пикселя. Соотношение сторон ограничено диапазоном [0.125, 8.0]. Коэффициент заполнения (fill ratio, отношение площади контура к площади bounding box) должен превышать 0.15.")

    body(doc, "Итоговый скор generic-предложения вычисляется по формуле:")
    formula(doc, "score = min(0.45,  0.10 + fill_ratio × 0.15 + area / (H × W))")
    caption(doc, "Формула 2 — Оценка качества generic-предложения")

    body(doc, "Из отфильтрованного набора берутся только top_k наиболее крупных по площади предложений (по умолчанию 12). Это ограничение необходимо для управления вычислительной нагрузкой на последующий CLIP-инференс.")

    add_heading(doc, "5.3. Объединение предложений и Non-Maximum Suppression", level=2)

    body(doc, "После получения двух списков предложений они объединяются и подаются на вход алгоритму Non-Maximum Suppression с порогом перекрытия IoU=0.45. NMS устраняет дублирующиеся регионы, оставляя для каждой группы перекрывающихся боксов лишь один с наибольшим скором. Предварительно каждому предложению применяется expand_box с масштабом 8% — это общий этап расширения перед NMS.")

    body(doc, "Метрика Intersection over Union (IoU) для двух прямоугольников A и B определяется стандартным образом:")
    formula(doc, "IoU(A, B) = Area(A ∩ B) / Area(A ∪ B)")
    caption(doc, "Формула 3 — Intersection over Union")

    body(doc, "Финальное число предложений ограничивается сверху параметром max_proposals (по умолчанию 24). Это критически важное ограничение: для каждого предложения будет запущен полноценный CLIP-инференс, стоимость которого на GPU составляет около 3–8 мс, но в совокупности при большом числе предложений может стать узким местом.")

    # ─────────────────────────────────────
    # 6. ОЦЕНКА НОВИЗНЫ
    # ─────────────────────────────────────
    add_heading(doc, "6. Этап 2: Оценка новизны через OpenCLIP", level=1)
    add_heading(doc, "6.1. Вычисление косинусного сходства", level=2)

    body(doc, "Для каждого кандидатного региона вырезается кроп из оригинального изображения по координатам bounding box. Кроп переводится из пространства BGR (используемого OpenCV) в RGB, конвертируется в PIL Image и обрабатывается препроцессором OpenCLIP: изменение размера до 224×224, центральное кропирование, нормализация по каналам. Получившийся тензор подаётся на вход визуальному кодировщику CLIP, и выходной вектор L2-нормализуется.")

    body(doc, "Параллельно формируются нормализованные текстовые эмбеддинги для всего набора известных классов (prompt ensembling, описанный в разделе 3.2). Косинусное сходство визуального вектора v и каждого текстового вектора tᵢ вычисляется как скалярное произведение нормализованных векторов:")
    formula(doc, "sim(v, tᵢ) = (v / ‖v‖) · (tᵢ / ‖tᵢ‖)")
    caption(doc, "Формула 4 — Косинусное сходство между визуальным и текстовым эмбеддингами")

    body(doc, "Вектор сходств подаётся на softmax с температурой 10.0 для получения вероятностного распределения по классам. Температурный параметр умышленно выбран достаточно высоким (что соответствует «мягкому» распределению), поскольку излишне острая softmax при малых разницах сходств создаёт ложную уверенность.")
    formula(doc, "P(kᵢ | v) = exp(sim(v, tᵢ) × 10.0) / Σⱼ exp(sim(v, tⱼ) × 10.0)")
    caption(doc, "Формула 5 — Вероятность принадлежности к классу kᵢ")

    body(doc, "Из вектора сходств извлекаются: top label (класс с максимальным сходством), top similarity (числовое значение этого сходства), second similarity (сходство со вторым лучшим классом), top probability (вероятность согласно softmax) и margin = top_similarity - second_similarity — мера уверенности, показывающая, насколько лучший класс превосходит второго претендента.")

    add_heading(doc, "6.2. Алгоритм принятия решения «известный/неизвестный»", level=2)

    body(doc, "Классификация предложения как «известного» (known) или «неизвестного» (Unknown) основана на нескольких взаимодействующих критериях, учитывающих источник предложения (YOLO или generic) и несколько пороговых значений.")

    body(doc, "Для YOLO-предложений вводится понятие yolo_supports_known — условие, при котором детектор сильной рукой «подтверждает» принадлежность к известному классу. Оно выполняется, если одновременно: a) уверенность YOLO не ниже yolo_support_confidence (по умолчанию 0.35); б) YOLO-метка принадлежит множеству известных классов; в) текстовая метка CLIP совпадает с YOLO-меткой или CLIP-сходство привышает known_similarity_threshold (0.24).")

    body(doc, "Формально итоговое решение для YOLO-предложений выглядит следующим образом:")
    formula(doc, "is_known_YOLO = yolo_supports_known OR\n"
                  "               (top_sim >= strong_threshold AND margin >= 0.005)")
    caption(doc, "Формула 6 — Условие «известности» для YOLO-предложений")

    body(doc, "Для generic-предложений используется более строгий критерий, не опирающийся на поддержку детектора:")
    formula(doc, "is_known_GENERIC = top_sim >= strong_threshold\n"
                  "               AND top_prob >= 0.20\n"
                  "               AND margin >= margin_threshold")
    caption(doc, "Формула 7 — Условие «известности» для generic-предложений")

    body(doc, "Здесь strong_similarity_threshold = 0.30 — основной порог, разделяющий известные и неизвестные объекты по CLIP-сходству. Это значение подобрано эмпирически и является наиболее критичным параметром системы. Завышение порога увеличивает чувствительность (больше объектов помечается как Unknown), занижение — снижает её и порождает ложные срабатывания.")

    add_heading(doc, "6.3. Вычисление novelty score", level=2)

    body(doc, "Для каждого предложения, вне зависимости от итоговой классификации, вычисляется непрерывная оценка новизны unknown_score ∈ [0, 1]. Чем ближе значение к 1, тем более «чужеродным» выглядит объект. Эта оценка полезна при сортировке Unknown-объектов по степени необычности и при построении порогового фильтра на этапе пользовательского просмотра.")

    body(doc, "Оценка складывается из двух компонент — недостатка сходства и недостатка маржи:")
    formula(doc, "novelty_sim  = max(0,  strong_thr - top_sim) / strong_thr\n"
                  "novelty_marg = max(0,  margin_thr - margin) / margin_thr\n"
                  "unknown_score = clip(0.65 × novelty_sim + 0.35 × novelty_marg, 0, 1)")
    caption(doc, "Формула 8 — Взвешенная оценка новизны объекта")

    body(doc, "Веса 0.65 (для сходства) и 0.35 (для маржи) отражают относительную информативность двух компонент: косинусное сходство несёт основную нагрузку по оценке семантической близости к известным классам, тогда как margin выступает вспомогательным сигналом о надёжности самого прогноза. Для известных объектов оценка пересчитывается как 1 − top_probability, что интерпретируется как «обратная уверенность».")

    # ─────────────────────────────────────
    # 7. ОЦЕНКА ГЛУБИНЫ
    # ─────────────────────────────────────
    add_heading(doc, "7. Этап 3: Пространственный анализ через монокулярную глубину", level=1)

    body(doc, "После получения предсказаний новизны для всех предложений плагин параллельно (или последовательно, в зависимости от доступности GPU) вычисляет карту относительной глубины сцены. Как было описано в разделе 3.3, для этой цели применяется модель DPT-Hybrid-MiDaS.")

    body(doc, "Для каждой обнаруженной зоны (известной или неизвестной) вычисляется медиана значений глубины в центральной 60% части ограничивающего прямоугольника (отступ 20% от каждой стороны). Сужение зоны анализа до внутренней части бокса снижает влияние фона, проникающего в область граничных пикселей. Медиана предпочтительнее среднего как мера центральной тенденции, поскольку устойчива к выбросам — резким перепадам глубины на краях объектов.")

    body(doc, "Нормализация значений глубины производится по 5-му и 95-му процентилям всей карты, что позволяет диапазон значений «растянуть» до [0, 1] с отсечением выбросов:")
    formula(doc, "depth_score = clip((raw_depth - P5) / (P95 - P5), 0, 1)")
    caption(doc, "Формула 9 — Нормализованная оценка глубины объекта")

    body(doc, "На основе нормализованного значения каждый объект относится к одному из трёх пространственных поясов: «near» (score ≥ 0.66) — ближний план, «mid» (0.33 ≤ score < 0.66) — средний план, «far» (score < 0.33) — дальний план. Дополнительно каждому объекту присваивается ранг глубины (depth_rank) — его порядковый номер при сортировке от ближнего к дальнему.")

    body(doc, "Пространственные метки существенно обогащают отчёты и визуализацию: аннотированные изображения содержат информацию о том, что детектированный неизвестный объект находится, например, на переднем плане — это важный сигнал для оператора системы видеонаблюдения, поскольку именно ближние объекты, как правило, представляют наибольший оперативный интерес.")

    # ─────────────────────────────────────
    # 8. КЛАСТЕРИЗАЦИЯ
    # ─────────────────────────────────────
    add_heading(doc, "8. Этап 4: Кластеризация неизвестных объектов", level=1)
    add_heading(doc, "8.1. Сохранение кропов", level=2)

    body(doc, "Все объекты, отнесённые к классу Unknown, вырезаются из исходного изображения и сохраняются на диск в виде отдельных JPEG-файлов. Перед вырезанием ограничивающий прямоугольник расширяется на unknown_crop_margin_scale (по умолчанию 12%) — это добавляет небольшой пространственный контекст и улучшает визуальное распознавание при ручном просмотре. Для каждого кропа вычисляется CLIP-эмбеддинг, который сохраняется в оперативной памяти и используется на следующем этапе кластеризации.")

    body(doc, "Имена сохраняемых файлов включают префикс исходного файла и порядковый номер неизвестного объекта — например, «img001_unknown_001.jpg». Для видеофайлов в имя кропа дополнительно включается индекс кадра и временная метка в формате HH-MM-SS_mmm.")

    add_heading(doc, "8.2. Локальная кластеризация по схожести", level=2)

    body(doc, "Накопленный набор кропов (для изображения — все Unknown-объекты, обнаруженные в этом файле; для видео — по всем проанализированным ключевым кадрам) подвергается кластеризации для выявления визуально схожих групп. Функция _cluster_unknown_crops_to_folder реализует жадный инкрементальный алгоритм кластеризации:")

    body(doc, "Для каждого нового кропа вычисляется косинусное сходство его CLIP-эмбеддинга с центроидами всех уже сформированных кластеров. Если максимальное сходство превышает порог unknown_class_similarity_threshold (по умолчанию 0.88), кроп присоединяется к наиболее похожему кластеру; центроид обновляется как нормализованное среднее всех эмбеддингов кластера. Если ни один кластер не достигает порога, создаётся новый кластер с именем UnknownClass_001, UnknownClass_002 и т.д.")

    formula(doc, "centroid_new = normalize( mean( embeddings_cluster ∪ {emb_new} ) )")
    caption(doc, "Формула 10 — Обновление центроида кластера")

    body(doc, "Каждый кластер превращается в отдельную подпапку результирующей директории «_openset_unknown_classes». Кропы физически копируются в соответствующую подпапку. Таким образом, после обработки файла пользователь получает структурированную директорию, в которой схожие неизвестные объекты сгруппированы вместе, что существенно упрощает ручной просмотр и анализ.")

    add_heading(doc, "8.3. Консолидация базы Unknown-классов", level=2)

    body(doc, "Плагин дополнительно включает функцию consolidate_unknown_class_database, предназначенную для ретроспективного объединения классов в глобальной базе UnknownClassDB. В отличие от локальной кластеризации (по одному файлу), консолидация работает над всей накопленной базой.")

    body(doc, "Алгоритм консолидации — итеративная жадная агломерация: на каждом шаге находится пара кластеров с наибольшим косинусным сходством центроидов; если это сходство превышает заданный порог (similarity_threshold), меньший по числу примеров кластер поглощается большим. Файлы физически перемещаются, опустевшая папка удаляется. Итерации продолжаются до тех пор, пока не останется ни одной пары выше порога.")

    body(doc, "Вычислительная сложность каждой итерации составляет O(M²) по числу кластеров M — это полный перебор всех пар. Для типичных баз, содержащих десятки или первые сотни классов, данная сложность является вполне приемлемой. При необходимости для баз с тысячами классов данный подход может быть заменён на приближённый поиск ближайших соседей (FAISS, HNSW) без изменения семантики алгоритма.")

    # ─────────────────────────────────────
    # 9. ПАРАМЕТРЫ КОНФИГУРАЦИИ
    # ─────────────────────────────────────
    add_heading(doc, "9. Параметры конфигурации и их влияние на качество работы", level=1)

    body(doc, "OpenSetAnalyzer предоставляет развитую систему параметризации, позволяющую адаптировать поведение плагина к конкретным сценариям применения. Ниже каждый параметр рассматривается с точки зрения его физического смысла и практического эффекта.")

    body(doc, "det_confidence (по умолчанию 0.15) — нижний порог уверенности детектора YOLO. Снижение этого значения увеличивает полноту генератора предложений: детектор срабатывает на менее чёткие объекты, что важно для обнаружения частично перекрытых или малоразмерных unknown-объектов. Однако слишком низкий порог порождает избыточное число предложений с размытыми границами, увеличивая нагрузку на CLIP-инференс.")

    body(doc, "known_similarity_threshold (по умолчанию 0.24) — мягкий порог для CLIP-сходства при поддержке YOLO. Участвует только в условии yolo_supports_known и используется как более снисходительный критерий: если YOLO подтверждает класс с высокой уверенностью, достаточно лишь незначительного согласия со стороны CLIP.")

    body(doc, "strong_similarity_threshold (по умолчанию 0.30) — главный порог новизны. Это наиболее чувствительный параметр системы. Объекты с CLIP-сходством ниже этого значения автоматически классифицируются как Unknown (при выполнении прочих условий). Значение 0.30 соответствует умеренно-строгой позиции: к неизвестным относятся объекты с выраженной семантической «чужеродностью», тогда как пограничные случаи (атипичные ракурсы автомобилей, сильно окклюдированные люди) трактуются как известные.")

    body(doc, "margin_threshold (по умолчанию 0.015) — минимальная разница между первым и вторым местами по CLIP-сходству. Малая маржа означает, что объект «колеблется» между двумя классами — что само по себе является косвенным признаком нетипичности. При значениях margin < margin_threshold даже объекты с достаточным top_similarity могут быть признаны неизвестными (в случае generic-предложений).")

    body(doc, "yolo_support_confidence (по умолчанию 0.35) — порог уверенности YOLO для учёта как сильной поддержки классификации. Устанавливается в два-три раза выше det_confidence. Логика: высокоуверенные YOLO-детекции, как правило, соответствуют хорошо локализованным объектам из тренировочного распределения, и их мнению можно доверять при принятии решения об известности.")

    body(doc, "generic_top_k (по умолчанию 12) и max_proposals (по умолчанию 24) — ограничения на число предложений. Увеличение max_proposals позволяет охватить больше потенциальных объектов ценой роста времени обработки. Соотношение этих параметров определяет, насколько активно задействуется контурный генератор против YOLO: при YOLO_proposals < max_proposals оставшийся «бюджет» заполняется generic-предложениями.")

    body(doc, "unknown_class_similarity_threshold (по умолчанию 0.88) — порог для кластеризации Unknown-объектов. При высоких значениях (0.92–0.95) каждый визуально уникальный объект образует отдельный класс; при низких (0.75–0.80) визуально разнородные объекты агрессивно объединяются в немногочисленные крупные кластеры. Для большинства практических сценариев оптимум лежит в диапазоне 0.85–0.92.")

    # ─────────────────────────────────────
    # 10. ОБРАБОТКА ВИДЕО
    # ─────────────────────────────────────
    add_heading(doc, "10. Особенности обработки видеопотока", level=1)

    body(doc, "Обработка видеофайлов реализована в функции analyze_open_set_video и принципиально отличается от покадрового анализа: вместо обработки каждого кадра система применяет равномерную выборку с заданным временным интервалом sample_interval_seconds (по умолчанию 1.0 с). Шаг выборки в кадрах вычисляется как frame_step = round(fps × sample_interval_seconds).")

    body(doc, "Данная стратегия продиктована двумя соображениями. Во-первых, последовательные кадры видео несут высококоррелированную информацию: в большинстве типичных сцен за 1/25 или 1/30 секунды содержание кадра изменяется незначительно. Во-вторых, полный покадровый анализ YOLO + CLIP + DPT был бы крайне медленным (порядка 0.5–2 с на кадр при работе на GPU), что сделало бы обработку часового видео непрактичной.")

    body(doc, "Для каждого выбранного ключевого кадра полностью запускается весь конвейер (предложения, CLIP, глубина). Аннотированные кадры записываются в выходное видео MP4 (VideoWriter, кодек mp4v), а отдельные ключевые кадры с Unknown-объектами сохраняются как JPEG-изображения. Для каждого такого кадра фиксируются временная метка в формате HH:MM:SS.mmm и абсолютный индекс кадра.")

    body(doc, "По завершении обработки формируется текстовый файл таймкодов (unknown_timestamps), содержащий перечень ключевых кадров с ненулевым числом неизвестных объектов в readable-формате. Данный файл предназначен для быстрого поиска мест в видео, требующих ручного досмотра оператором.")

    body(doc, "Максимальное число сохраняемых ключевых кадров ограничено параметром max_keyframes (по умолчанию 12). Этот лимит распространяется только на сохранение аннотированных кадров: анализ всех ключевых кадров выполняется в любом случае. Все Unknown-кропы из всех ключевых кадров накапливаются в единый список и обрабатываются совместной кластеризацией по окончании видеоразбора.")

    # ─────────────────────────────────────
    # 11. АННОТИРОВАНИЕ
    # ─────────────────────────────────────
    add_heading(doc, "11. Визуализация результатов", level=1)

    body(doc, "Аннотирование результатов анализа выполняется непосредственно поверх исходного изображения (или кадра) с помощью библиотеки OpenCV. Для каждого обнаруженного объекта на изображение наносится ограничивающий прямоугольник с цветовой кодировкой: зелёный (0, 200, 0) для известных объектов и оранжевый (0, 140, 255) в пространстве BGR для неизвестных. Цветовой выбор обоснован максимальной контрастностью относительно типичного содержимого кадра видеонаблюдения.")

    body(doc, "Над каждым боксом отображается подпись, структурированная как «Label[depth_bucket] [confidence]», где Label — предсказанный класс или «Unknown», depth_bucket — пространственное расположение («near», «mid», «far»), а confidence — для известных объектов CLIP-вероятность, для неизвестных — unknown_score. Текст выводится на тёмном полупрозрачном фоне (заливка прямоугольника цветом 20,20,20) с субпиксельным антиалиасингом (cv2.LINE_AA) для удобочитаемости.")

    body(doc, "Аннотированный файл сохраняется рядом с исходным с суффиксом _openset_annotated. Это ненавязчивое именование позволяет сохранить оригинальный файл нетронутым и организовать параллельное хранение результатов без риска перезаписи исходных данных.")

    body(doc, "Для видеофайлов помимо сохранения отдельных кадров производится запись аннотированного видео с суффиксом _openset_annotated.mp4. Частота кадров аннотированного видео вычисляется как fps / frame_step, что обеспечивает «нормальную» скорость просмотра: каждый ключевой кадр воспроизводится в реальном времени. При этом визуально видео не содержит статичных эпизодов — оно состоит исключительно из обработанных ключевых кадров.")

    # ─────────────────────────────────────
    # 12. ОТЧЁТНОСТЬ
    # ─────────────────────────────────────
    add_heading(doc, "12. Система отчётности и интеграция с Watch Golem", level=1)

    body(doc, "По итогам обработки плагин возвращает словарь результатов, содержащий исчерпывающую информацию о каждом обнаруженном объекте: тип (известный/неизвестный), координаты bounding box, метку CLIP, числовые значения сходства, вероятности и маржи, метку и скор глубины, ранг по глубине, путь к сохранённому кропу (для Unknown) и имя кластера (после кластеризации). Этот словарь является единой точкой входа для всех отчётных функций.")

    body(doc, "Функция generate_report_open_set формирует структурированный текстовый отчёт, в котором для каждого проанализированного файла выводится сводная статистика (число обнаруженных объектов, используемые пороги, информация о модели глубины) и детальная поопъектная таблица. Для видеофайлов отчёт дополнительно содержит поэпизодный разбор по ключевым кадрам.")

    body(doc, "Функция generate_report_word_open_set создаёт Word-документ (.docx) с аналогичным содержанием, дополненный встроенными аннотированными изображениями. Размер изображений при вставке ограничен значением available_width × 0.95 по ширине страницы для корректного отображения в документе.")

    body(doc, "В составе Watch Golem обработка плагином организована через фоновый рабочий поток (QThread: OpenSetAnalysisWorker), что обеспечивает неблокирующую работу пользовательского интерфейса во время ресурсоёмких операций. Callback-функция прогресса передаётся в плагин и вызывается на каждом шаге конвейера, что позволяет отображать прогрессбар с информативными подписями типа «Анализ кадра 00:05:32.000 (45/120)».")

    # ─────────────────────────────────────
    # 13. БАЗА UNKNOWNCLASSDB
    # ─────────────────────────────────────
    add_heading(doc, "13. База неизвестных классов UnknownClassDB", level=1)

    body(doc, "UnknownClassDB — это персистентная файловая база данных, накапливающая сведения о неизвестных объектах, обнаруженных в ходе всех сессий работы системы. Структурно база представляет собой директорию UnknownClassDB/Classes/, в которой каждому автоматически выявленному визуальному кластеру соответствует подпапка с именем UnknownClass_001, UnknownClass_002 и т.д. Каждая такая подпапка содержит кропы всех изображений, отнесённых к данному кластеру.")

    body(doc, "Дополнительно в корне базы хранятся два метафайла: UNKNOWN_CLASS_DATABASE_REPORT.txt (текстовый отчёт в readable-формате) и UNKNOWN_CLASS_DATABASE_REPORT.json (машиночитаемый JSON со всеми метаданными о кластерах, исходных путях, значениях сходства и сводной статистикой). JSON-отчёт используется функцией _load_unknown_class_database_metadata для восстановления метаданных изображений при повторной загрузке базы без повторного инференса CLIP.")

    body(doc, "Сопутствующий плагин UnknownClassMerger предоставляет функциональность ручного пополнения базы из произвольных папок, а также консолидации базы (функция consolidate_unknown_class_database). Разделение ответственности между OpenSetAnalyzer (автоматическое обнаружение и локальная кластеризация) и UnknownClassMerger (ручной импорт и консолидация) отражает двухэтапную идеологию управления знаниями о новых объектах: сначала система накапливает кандидатов, затем человек-оператор принимает решение о включении их в постоянную базу.")

    body(doc, "Загрузка базы при каждом запуске функции кластеризации/консолидации требует повторного инференса CLIP для всех изображений, поскольку эмбеддинги не хранятся на диске из соображений гибкости (возможность смены модели CLIP без миграции данных). Это является известным узким местом при больших объёмах базы. Возможное направление оптимизации — кеширование эмбеддингов в отдельных .npy файлах рядом с исходными кропами.")

    # ─────────────────────────────────────
    # 14. ОБСУЖДЕНИЕ И ОГРАНИЧЕНИЯ
    # ─────────────────────────────────────
    add_heading(doc, "14. Обсуждение результатов и ограничения подхода", level=1)

    body(doc, "Предложенный подход к open-set detection через комбинацию YOLO + OpenCLIP обладает рядом принципиальных достоинств. Прежде всего, он не требует дообучения нейронных сетей при изменении множества известных классов: достаточно обновить список меток, и CLIP автоматически перестраивает пространство сравнения. Это делает систему крайне гибкой в условиях быстро меняющихся требований к мониторингу.")

    body(doc, "Второе достоинство — независимость от закрытых наборов данных. OpenCLIP ViT-B-32 с предобучением на LAION-2B демонстрирует широкое покрытие семантического пространства, включая многие объекты, не представленные в YOLO COCO-словаре. Это расширяет список «известных» классов далеко за пределы 80 категорий объектного детектора.")

    body(doc, "Вместе с тем подход имеет ряд ограничений. Наиболее существенное из них связано с природой CLIP: модель обучена на описаниях Интернета и хорошо знает «популярные» объекты, однако специфические промышленные артефакты, военное оборудование, редкие животные или нестандартные конструкции могут иметь неопределённые косинусные сходства с несвязанными классами, что затрудняет надёжное отнесение их к классу Unknown.")

    body(doc, "Проблема генерации предложений также является источником погрешности. YOLO, обученный на COCO, может вообще не генерировать bounding box для объекта, разительно непохожего на все 80 тренировочных классов (например, крупный странный предмет неизвестной формы). В таком случае задача перекладывается на generic proposals — контурный генератор, который, в свою очередь, не всегда корректно сегментирует объекты сложной формы или низкоконтрастные объекты.")

    body(doc, "Ещё одно ограничение связано с разрешением CLIP: модель ViT-B-32 обрабатывает изображения как набор патчей 32×32 пикселя — объекты меньше ~64×64 пикселей в оригинальном изображении будут представлены лишь несколькими патчами, что снижает точность их характеризации. Для задач обнаружения мелких объектов рекомендуется использование модели ViT-L-14 или ViT-G-14 с более мелкими патчами.")

    body(doc, "Оценка глубины через DPT-Hybrid-MiDaS добавляет ценную пространственную информацию, но имеет ограничение, уже упоминавшееся ранее: модель работает только при наличии GPU. Ни один из компонентов системы критично не зависит от этой оценки — она является опциональным дополнением, и при её отсутствии все прочие функции продолжают работать в полном объёме.")

    body(doc, "Говоря об общей производительности, следует отметить, что на типичного класса GPU (NVIDIA RTX 3060–4080) полная обработка одного изображения занимает 1–4 секунды, включая все три нейросетевых инференса. Первый запуск медленнее вследствие инициализации (загрузка весов YOLO занимает ~1–3 с, OpenCLIP ~5–10 с, DPT ~3–8 с), но при батчевой обработке амортизированная стоимость существенно снижается.")

    body(doc, "С точки зрения архитектурных альтернатив следует упомянуть несколько подходов, которые могут быть интегрированы или заменены в будущих версиях плагина. Использование Grounding DINO — открытой мультимодальной детекционной модели — позволило бы объединить предложение регионов и оценку открытого множества в одном инференсе. Segment Anything Model (SAM) предоставляет качественную сегментацию для любого региона, что могло бы заменить контурный генератор generic proposals. Наконец, применение методов energy-based out-of-distribution detection поверх финального слоя детектора (по типу VOS или STUD) могло бы дополнить CLIP-новизну дискриминативным сигналом из пространства признаков самого YOLO.")

    # ─────────────────────────────────────
    # 15. ЗАКЛЮЧЕНИЕ
    # ─────────────────────────────────────
    add_heading(doc, "15. Заключение", level=1)

    body(doc, "В настоящей работе представлено подробное описание программного плагина OpenSetAnalyzer, реализующего задачу open-set object detection в системе видеомониторинга Watch Golem. Разработанный плагин основывается на многокомпонентном конвейере, объединяющем три взаимодополняющих нейросетевых модуля — детектор объектов YOLO, контрастивную мультимодальную модель OpenCLIP и монокулярный оценщик глубины DPT-Hybrid-MiDaS — с геометрическим генератором кандидатных регионов.")

    body(doc, "Принципиальное отличие предложенного подхода от традиционных методов компьютерного зрения состоит в нуль-шотной оценке семантической новизны через CLIP: система способна корректно маркировать объекты, которые никогда не встречались при обучении, не требуя при этом никакой переработки нейронных сетей. Это свойство делает плагин особенно ценным в динамичных операционных средах, где список потенциально значимых объектов заранее неизвестен или быстро эволюционирует.")

    body(doc, "Система кластеризации неизвестных объектов обеспечивает автоматическую организацию обнаруженных аномалий в семантически связные группы, что значительно упрощает последующий ручной анализ и создаёт задел для систематического накопления знаний о новых классах. Потенциальным развитием данного направления является активное обучение (active learning): оператор мог бы размечать наиболее информативные кластеры, и система — дообучаться на этих метках для улучшения будущих детекций.")

    body(doc, "Среди направлений дальнейших исследований выделяется несколько ключевых. Во-первых, интеграция Grounding DINO или аналогичных открытых детекторов с развитой мультимодальной поддержкой могла бы устранить зависимость от двухступенчатой схемы YOLO + CLIP. Во-вторых, поддержка онлайн-обработки потокового видео с применением трекеров (SORT, ByteTrack) позволила бы связывать обнаружения одного и того же неизвестного объекта на разных кадрах и накапливать более устойчивые эмбеддинги. В-третьих, введение конфигурируемых профилей сцен (промышленный объект / городская улица / закрытое помещение) с настройкой различных порогов новизны под каждый профиль позволило бы снизить число ложных срабатываний в хорошо изученных сценариях без потери чувствительности в нестандартных ситуациях.")

    body(doc, "Таким образом, OpenSetAnalyzer является практически применимой и теоретически обоснованной реализацией концепции открытого множества, способной существенно расширить аналитические возможности современных систем видеомониторинга по сравнению с традиционными closed-set детекторами.")

    # ─────────────────────────────────────
    # СПИСОК ЛИТЕРАТУРЫ
    # ─────────────────────────────────────
    add_heading(doc, "Список литературы", level=1)

    refs = [
        "1. Redmon J., Divvala S., Girshick R., Farhadi A. You Only Look Once: Unified, Real-Time Object Detection // Proceedings of CVPR, 2016. — P. 779–788.",
        "2. Jocher G. et al. Ultralytics YOLO. [Электронный ресурс]. — URL: https://github.com/ultralytics/ultralytics (дата обращения: 11.04.2026).",
        "3. Radford A., Kim J.W., Hallacy C. et al. Learning Transferable Visual Models From Natural Language Supervision // Proceedings of ICML, 2021. — Vol. 139. — P. 8748–8763.",
        "4. Cherti M., Beaumont R., Wightman R. et al. Reproducible scaling laws for contrastive language-image learning // Proceedings of CVPR, 2023. — P. 2818–2829.",
        "5. Ranftl R., Bochkovskiy A., Koltun V. Vision Transformers for Dense Prediction // Proceedings of ICCV, 2021. — P. 12179–12188.",
        "6. Ranftl R., Lasinger K., Hafner D. et al. Towards Robust Monocular Depth Estimation: Mixing Datasets for Zero-Shot Cross-Dataset Transfer // IEEE Transactions on Pattern Analysis and Machine Intelligence, 2022. — Vol. 44(3). — P. 1623–1637.",
        "7. Dosovitskiy A., Beyer L., Kolesnikov A. et al. An Image is Worth 16x16 Words: Transformers for Image Recognition at Scale // Proceedings of ICLR, 2021.",
        "8. Scheirer W.J., de Rezende Rocha A., Sapkota A., Boult T.E. Toward Open Set Recognition // IEEE Transactions on Pattern Analysis and Machine Intelligence, 2013. — Vol. 35(7). — P. 1757–1772.",
        "9. Joseph K.J., Khan S., Khan F.S., Balasubramanian V.N. Towards Open World Object Detection // Proceedings of CVPR, 2021. — P. 5830–5840.",
        "10. Hendrycks D., Gimpel K. A Baseline for Detecting Misclassified and Out-of-Distribution Examples in Neural Networks // Proceedings of ICLR, 2017.",
        "11. Liu W., Wang X., Owens J., Li Y. Energy-Based Out-of-Distribution Detection // Advances in Neural Information Processing Systems (NeurIPS), 2020. — Vol. 33. — P. 21464–21475.",
        "12. Kirillov A., Mintun E., Ravi N. et al. Segment Anything // Proceedings of ICCV, 2023. — P. 4015–4026.",
        "13. Liu S., Zeng Z., Ren T. et al. Grounding DINO: Marrying DINO with Grounded Pre-Training for Open-Set Object Detection // European Conference on Computer Vision, 2024.",
        "14. Miller D., Nicholson L., Dayoub F., Sünderhauf N. Dropout Sampling for Robust Object Detection in Open-Set Conditions // Proceedings of ICRA, 2018. — P. 3243–3249.",
        "15. Vaze S., Han K., Vedaldi A., Zisserman A. Open-Set Recognition: A Good Closed-Set Classifier is All You Need // Proceedings of ICLR, 2022.",
    ]

    for ref in refs:
        p = doc.add_paragraph()
        p.paragraph_format.first_line_indent = Cm(-1.25)
        p.paragraph_format.left_indent = Cm(1.25)
        p.paragraph_format.space_after = Pt(3)
        p.paragraph_format.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
        run = p.add_run(ref)
        run.font.size = Pt(12)
        run.font.name = "Times New Roman"

    doc.save(OUTPUT_PATH)
    print(f"Документ сохранён: {OUTPUT_PATH}")
